int main() {
    const std::string word = "mississippi";
    int count = 0;
    for (char c : word) {
        if (c == 's') {
            ++count;
        }
    }
    std::cout << "s count: " << count << '\n';

    const std::string fruit = "banana";
    std::string replaced;
    for (std::size_t i = 0; i < fruit.size(); ++i) {
        if (fruit[i] == 'a') {
            replaced += '4';
        } else {
            replaced += fruit[i];
        }
    }
    std::cout << replaced << '\n';
    return 0;
}

