#include <cctype>
#include <iostream>
#include <string>

int main() {
    const std::string code = "a1b2c3";
    int digitSum = 0;
    for (char c : code) {
        if (std::isdigit(static_cast<unsigned char>(c))) {
            digitSum += c - '0';
        }
    }
    std::cout << "Digit sum: " << digitSum << '\n';

    std::cout << "Code of A: " << static_cast<int>('A') << '\n';

    const std::string word = "zebra";
    const int shift = 3;
    std::string shifted;
    for (char c : word) {
        const int pos = (c - 'a' + shift) % 26;
        shifted += static_cast<char>('a' + pos);
    }
    std::cout << "Shifted: " << shifted << '\n';
    return 0;
}

